57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    private final AddressNormalizer addressNormalizer;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper,
76	                                 AddressNormalizer addressNormalizer) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	        this.addressNormalizer = addressNormalizer;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String address = addressNormalizer.normalize(owner.getAddress());
115	        if (address.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	        }
118	        owner.setAddress(address);
119	        String telephone = toE164(owner.getTelephone());
120	        if (telephone == null) {
121	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	        }
123	        owner.setTelephone(telephone);
124	        LocalDate effectiveDate = owner.getRegistrationDate() != null
125	            ? owner.getRegistrationDate() : LocalDate.now();
126	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
127	        if (isDailyLimitReached(owner.getRegistrationDate())) {
128	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
129	        }
130	        if (isTelephoneInUse(telephone)) {
131	            return new ResponseEntity<>(HttpStatus.CONFLICT);
132	        }
133	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
134	        if (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
135	            return new ResponseEntity<>(HttpStatus.CONFLICT);
136	        }
137	        if (sharesHousehold) {
138	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
139	        }
140	        if (isCityAtCapacity(owner.getCity())) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
144	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
145	        this.clinicService.saveOwner(owner);
146	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
147	        headers.setLocation(UriComponentsBuilder.newInstance()
148	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
149	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
150	    }
151	
152	    /**
153	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
154	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
155	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
156	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
157	     */
158	    private String nextCustomerCode(String city, String lastName) {
159	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
160	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
161	        int sequence = (int) this.clinicService.findAllOwners().stream()
162	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
163	            .count() + 1;
164	        return String.format("%s-%s-%04d", city3, last3, sequence);
165	    }
166	
167	    /**
168	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
169	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
170	     * (business-day) registration date of the owner being created, so owners are counted per
171	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
172	     */
173	    private boolean isDailyLimitReached(LocalDate day) {
174	        long count = this.clinicService.findAllOwners().stream()
175	            .filter(existing -> day.equals(existing.getRegistrationDate()))
176	            .count();
177	        return count >= 100;
178	    }
179	
180	    /**
181	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
182	     * advance it to the following Monday; a weekday is returned unchanged.
183	     */
184	    private LocalDate toBusinessDay(LocalDate date) {
185	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
186	            date = date.plusDays(1);
187	        }
188	        return date;
189	    }
190	
191	    /**
192	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
193	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
194	     */
195	    private boolean isCityAtCapacity(String city) {
196	        long count = this.clinicService.findAllOwners().stream()
197	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
198	            .count();
199	        return count >= 50;
200	    }
201	
202	    /**
203	     * The number of existing owners that already share the given firstName and lastName,
204	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
205	     * whitespace runs collapsed). Counted over the owners present before this create.
206	     */
207	    private int namesakeCount(String firstName, String lastName) {
208	        String candidateFirstName = normalizeName(firstName);
209	        String candidateLastName = normalizeName(lastName);
210	        return (int) this.clinicService.findAllOwners().stream()
211	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
212	                && normalizeName(existing.getLastName()).equals(candidateLastName))
213	            .count();
214	    }
215	
216	    /**
217	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
218	     * cannot form a valid E.164 number.
219	     *
220	     * <p>A leading '+' and country code are kept when present; otherwise country code
221	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
222	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
223	     * carry 8 to 15 digits after the '+'.
224	     */
225	    private String toE164(String telephone) {
226	        if (telephone == null) {
227	            return null;
228	        }
229	        boolean hasCountryCode = telephone.trim().startsWith("+");
230	        String digits = telephone.replaceAll("\\D", "");
231	        String e164;
232	        if (hasCountryCode) {
233	            e164 = digits;
234	        } else {
235	            if (digits.startsWith("0")) {
236	                digits = digits.substring(1);
237	            }
238	            e164 = "61" + digits;
239	        }
240	        if (e164.length() < 8 || e164.length() > 15) {
241	            return null;
242	        }
243	        return "+" + e164;
244	    }
245	
246	    /**
247	     * Whether any existing owner already holds the given telephone number. Both the
248	     * candidate and each stored number are compared in E.164 form, so the check does not
249	     * depend on how each was originally formatted.
250	     */
251	    private boolean isTelephoneInUse(String telephone) {
252	        return this.clinicService.findAllOwners().stream()
253	            .map(Owner::getTelephone)
254	            .filter(Objects::nonNull)
255	            .map(this::toE164)
256	            .filter(Objects::nonNull)
257	            .anyMatch(telephone::equals);
258	    }
259	
260	    /**
261	     * Whether any existing owner already shares a household with the candidate, i.e. has both
262	     * the same lastName and the same address. Both fields are compared case-insensitively and
263	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
264	     * trimmed), so the check does not depend on casing or spacing.
265	     */
266	    private boolean isHouseholdInUse(String lastName, String address) {
267	        String candidateLastName = normalizeName(lastName);
268	        String candidateAddress = addressNormalizer.normalize(address);
269	        return this.clinicService.findAllOwners().stream()
270	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
271	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
272	    }
273	
274	    /**
275	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
276	     * to a single space and lower-case. A null value normalizes to the empty string.
277	     */
278	    private String normalizeName(String value) {
279	        if (value == null) {
280	            return "";
281	        }
282	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
283	    }
284	
285	    /**
286	     * A stable shared identifier for the household formed by a given lastName and address.
287	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
288	     * lastName and address, so every owner sharing the same household is assigned the same
289	     * value regardless of the order in which they are created. Formatted as the first 12
290	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
291	     */
292	    private String householdId(String lastName, String address) {
293	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
294	        try {
295	            byte[] digest = MessageDigest.getInstance("SHA-256")
296	                .digest(key.getBytes(StandardCharsets.UTF_8));
297	            StringBuilder sb = new StringBuilder(digest.length * 2);
298	            for (byte b : digest) {
299	                sb.append(String.format("%02x", b));
300	            }
301	            return sb.substring(0, 12).toUpperCase();
302	        }
303	        catch (NoSuchAlgorithmException e) {
304	            throw new IllegalStateException("SHA-256 not available", e);
305	        }
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
