316	        currentOwner.setCity(ownerFieldsDto.getCity());
317	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
318	        currentOwner.setLastName(ownerFieldsDto.getLastName());
319	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
320	        this.clinicService.saveOwner(currentOwner);
321	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
322	    }
323	
