329	        if (owner == null) {
330	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
331	        }
332	        this.clinicService.deleteOwner(owner);
333	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
334	    }
